-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0001_extensions.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0001_extensions.sql
-- PHASE 2 — Foundation extensions required by later migrations
-- =====================================================================

-- UUID generation (gen_random_uuid) is built into Postgres 13+ via pgcrypto,
-- Supabase ships pgcrypto enabled by default, but we enable explicitly
-- so this migration is self-contained and reproducible on a fresh project.
create extension if not exists "pgcrypto";

-- citext not required for MVP (kept out intentionally — email/slug matching
-- is handled at the application layer with normalized lowercase text).

-- Generic helper: keep updated_at in sync on every UPDATE.
-- Used by every table below that has an updated_at column.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0002_geography.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0002_geography.sql
-- Depends on: 0001_extensions.sql
-- Tables: provinces, districts
-- =====================================================================

create table public.provinces (
  id serial primary key,
  name_th text not null,
  name_en text not null,
  slug text not null unique,          -- Thai-language slug, e.g. 'นนทบุรี' (founder decision, updated after PHASE 2)
  region text,
  created_at timestamptz not null default now()
);

comment on table public.provinces is 'Thailand''s 77 provinces. Seeded once, rarely changes.';

create table public.districts (
  id serial primary key,
  province_id integer not null references public.provinces(id) on delete restrict,
  name_th text not null,
  name_en text not null,
  slug text not null,                 -- unique only within a province, not globally
  created_at timestamptz not null default now(),
  unique (province_id, slug)
);

comment on table public.districts is 'Amphoe/Khet within each province. ~928 rows nationwide.';

create index idx_districts_province_id on public.districts(province_id);


