-- Audit log — cheap to write now, essential the moment there is a
-- second admin, and useful for the single-founder case to answer
-- "why was this contractor suspended?" months later.
-- =====================================================================

create table public.admin_actions (
  id bigserial primary key,
  admin_id uuid not null references public.profiles(id) on delete restrict,
  action text not null,           -- e.g. 'approve_contractor', 'suspend_contractor', 'remove_review'
  target_type text,               -- e.g. 'contractor', 'review', 'report'
  target_id uuid,
  notes text,
  created_at timestamptz not null default now()
);

comment on table public.admin_actions is 'Audit log of every admin action. Written by application code on each admin operation, never edited or deleted.';

create index idx_admin_actions_admin on public.admin_actions(admin_id);
create index idx_admin_actions_target on public.admin_actions(target_type, target_id);


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0011_system_settings.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0011_system_settings.sql
-- Depends on: 0001_extensions.sql
-- Tables: system_settings
-- Purpose: config values (e.g. portfolio image limit) that must be
-- changeable by an admin WITHOUT a code deploy.
-- =====================================================================

create table public.system_settings (
  key text primary key,
  value jsonb not null,
  description text,
  -- SECURITY REVIEW FIX (post-PHASE-2, ChatGPT review item 3):
  -- get_setting() originally let ANY caller request ANY key. That is
  -- unsafe the moment a future admin-only setting (e.g. a feature flag
  -- controlling fraud thresholds) lands in this table — this column is
  -- the allowlist: only rows explicitly marked is_public are readable
  -- through get_setting(). Everything else requires is_admin().
  is_public boolean not null default false,
  updated_at timestamptz not null default now()
);

comment on table public.system_settings is 'Admin-editable configuration (limits, toggles). Read via public.get_setting() helper (respects is_public), never queried raw from anon/authenticated roles.';

create trigger trg_system_settings_updated_at
  before update on public.system_settings
  for each row execute function public.set_updated_at();

-- SECURITY DEFINER helper so contractors/anon can read a SPECIFIC setting
-- value (e.g. their portfolio limit) without being granted table-level
-- SELECT on system_settings. Only returns a value when the row is marked
-- is_public = true, OR the caller is admin/trusted service-role context —
-- this is the fix for ChatGPT review item 3 (design A: explicit allowlist
-- via is_public, chosen over B/C because it keeps a single simple
-- function signature the frontend already expects, while still letting
-- future admin-only settings exist safely in the same table).
create or replace function public.get_setting(setting_key text)
returns jsonb
language sql
security definer set search_path = public
stable
as $$
  select value from public.system_settings
  where key = setting_key
    and (is_public = true or public.is_trusted_context());
$$;

-- Defense in depth: even though get_setting() is SECURITY DEFINER and
-- filters internally, explicitly control who may call it at all — no
-- reason for an unauthenticated caller to be unable to call it (public
-- settings must work for anonymous visitors), but this makes the
-- intended callers explicit rather than implicit.
revoke execute on function public.get_setting(text) from public;
grant execute on function public.get_setting(text) to anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0012_denormalized_field_triggers.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0012_denormalized_field_triggers.sql
-- Depends on: 0005_contractors.sql, 0006_portfolio_images.sql, 0007_reviews.sql
-- Purpose: guarantee rating_avg / review_count / profile_completeness on
-- contractors can NEVER drift out of sync with their source rows, because
-- they are recalculated by trigger on every relevant change — never
-- written to directly by application code.
-- =====================================================================

-- ---------------------------------------------------------------------
-- rating_avg + review_count: recalculated from ACTIVE reviews only,
-- on any insert/update/delete on reviews.
-- ---------------------------------------------------------------------
create or replace function public.update_contractor_review_stats()
returns trigger
language plpgsql
as $$
declare
  target_contractor_id uuid;
begin
  target_contractor_id := coalesce(new.contractor_id, old.contractor_id);

  update public.contractors
  set
    rating_avg = coalesce((
      select round(avg(rating)::numeric, 1)
      from public.reviews
      where contractor_id = target_contractor_id and status = 'active'
    ), 0),
    review_count = (
      select count(*)
      from public.reviews
      where contractor_id = target_contractor_id and status = 'active'
    )
  where id = target_contractor_id;

  return coalesce(new, old);
end;
$$;

create trigger trg_reviews_update_contractor_stats
  after insert or update or delete on public.reviews
  for each row execute function public.update_contractor_review_stats();

-- ---------------------------------------------------------------------
-- profile_completeness: simple weighted checklist, recalculated whenever
-- a contractor row is updated (covers profile edits and portfolio-driven
-- updates via the application explicitly re-saving the contractor row).
-- Kept intentionally simple for MVP — not wired into ranking logic yet.
-- ---------------------------------------------------------------------
create or replace function public.calculate_profile_completeness(c public.contractors)
returns integer
language plpgsql
immutable
as $$
declare
  score integer := 0;
  has_portfolio boolean;
begin
  if c.business_name is not null and length(trim(c.business_name)) > 0 then score := score + 15; end if;
  if c.description is not null and length(trim(c.description)) > 20 then score := score + 15; end if;
  if c.profile_image_url is not null then score := score + 15; end if;
  if c.phone is not null or c.line_id is not null then score := score + 15; end if;
  if c.province_id is not null and c.district_id is not null then score := score + 10; end if;
  if c.years_experience is not null then score := score + 10; end if;

  select exists(select 1 from public.portfolio_images where contractor_id = c.id) into has_portfolio;
  if has_portfolio then score := score + 20; end if;

  return least(score, 100);
end;
$$;

create or replace function public.trg_set_profile_completeness()
returns trigger
language plpgsql
as $$
begin
  new.profile_completeness := public.calculate_profile_completeness(new);
  return new;
end;
$$;

create trigger trg_contractors_set_completeness
  before insert or update on public.contractors
  for each row execute function public.trg_set_profile_completeness();

-- Portfolio image changes also affect completeness (the "has_portfolio"
-- factor above) — touch the parent contractor row so the BEFORE UPDATE
-- trigger above recalculates it.
create or replace function public.touch_contractor_on_portfolio_change()
returns trigger
language plpgsql
as $$
declare
  target_contractor_id uuid;
begin
  target_contractor_id := coalesce(new.contractor_id, old.contractor_id);
  update public.contractors set updated_at = now() where id = target_contractor_id;
  return coalesce(new, old);
end;
$$;

create trigger trg_portfolio_images_touch_contractor
  after insert or delete on public.portfolio_images
  for each row execute function public.touch_contractor_on_portfolio_change();

-- ---------------------------------------------------------------------
-- Lock admin-only fields on contractors: a non-trusted caller (a normal
-- authenticated user or the contractor themself editing their own row)
-- cannot change status, verification_status, plan_tier, or
-- featured_until no matter what value they submit — those columns are
-- silently forced back to their previous value. Admins AND trusted
-- service-role (server-side) callers can change them.
--
-- SECURITY REVIEW FIX (post-PHASE-2, ChatGPT review item 1): originally
-- gated on public.is_admin() alone, which would have incorrectly blocked
-- a legitimate service-role server operation that has no auth.uid().
-- Now gated on public.is_trusted_context() (0004), which additionally
-- allows auth.role() = 'service_role'.
--
-- This runs alongside trg_contractors_set_completeness — both are
-- BEFORE UPDATE triggers on disjoint columns, so execution order between
-- them does not affect correctness.
-- ---------------------------------------------------------------------
create or replace function public.lock_contractor_admin_fields()
returns trigger
language plpgsql
as $$
begin
  if not public.is_trusted_context() then
    new.status := old.status;
    new.verification_status := old.verification_status;
    new.plan_tier := old.plan_tier;
    new.featured_until := old.featured_until;
  end if;
  return new;
end;
$$;

create trigger trg_contractors_lock_admin_fields
  before update on public.contractors
  for each row execute function public.lock_contractor_admin_fields();


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0013_rls_policies.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0013_rls_policies.sql
-- Depends on: every table migration above (0002–0011)
-- Enables RLS on EVERY table and defines policies per PHASE 1 strategy.
-- No table is left with RLS disabled. No policy trusts the frontend.
-- =====================================================================

-- Note: public.is_admin() is defined in 0004_profiles.sql (not here) so
-- that trigger functions in 0012 can use it before RLS policies exist.
-- It is used throughout the policies below.

-- =====================================================================
-- provinces / districts / categories — public reference data
-- =====================================================================
alter table public.provinces enable row level security;
alter table public.districts enable row level security;
alter table public.categories enable row level security;

create policy "provinces_select_all" on public.provinces
  for select using (true);
create policy "provinces_admin_write" on public.provinces
  for all using (public.is_admin()) with check (public.is_admin());

create policy "districts_select_all" on public.districts
  for select using (true);
create policy "districts_admin_write" on public.districts
  for all using (public.is_admin()) with check (public.is_admin());

create policy "categories_select_all" on public.categories
  for select using (true);
create policy "categories_admin_write" on public.categories
  for all using (public.is_admin()) with check (public.is_admin());

-- =====================================================================
-- profiles
-- =====================================================================
alter table public.profiles enable row level security;

create policy "profiles_select_own" on public.profiles
  for select using (auth.uid() = id or public.is_admin());
create policy "profiles_update_own" on public.profiles
  for update using (auth.uid() = id or public.is_admin())
  with check (auth.uid() = id or public.is_admin());
-- No public INSERT policy: rows are created only by the
-- handle_new_user() trigger (security definer) on signup.
create policy "profiles_admin_all" on public.profiles
  for all using (public.is_admin()) with check (public.is_admin());

-- =====================================================================
-- contractors
-- =====================================================================
alter table public.contractors enable row level security;

create policy "contractors_select_approved_public" on public.contractors
  for select using (status = 'approved' or user_id = auth.uid() or public.is_admin());

create policy "contractors_insert_own" on public.contractors
  for insert with check (user_id = auth.uid());

-- Ownership check only. Locking status/verification_status/plan_tier/
-- featured_until against self-approval is enforced by a BEFORE UPDATE
-- trigger (trg_contractors_lock_admin_fields, see 0012) rather than a
-- correlated-subquery WITH CHECK, which is unreliable to reason about
-- inside RLS — the trigger approach is deterministic and easy to audit.
create policy "contractors_update_own" on public.contractors
  for update using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());

create policy "contractors_admin_delete" on public.contractors
  for delete using (public.is_admin());

-- =====================================================================
-- contractor_categories
-- =====================================================================
alter table public.contractor_categories enable row level security;

create policy "contractor_categories_select" on public.contractor_categories
  for select using (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.status = 'approved')
    or exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  );

create policy "contractor_categories_owner_write" on public.contractor_categories
  for all using (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  )
  with check (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  );

-- =====================================================================
-- portfolio_images
-- =====================================================================
alter table public.portfolio_images enable row level security;

create policy "portfolio_images_select" on public.portfolio_images
  for select using (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.status = 'approved')
    or exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  );

create policy "portfolio_images_owner_write" on public.portfolio_images
  for all using (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  )
  with check (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  );

-- =====================================================================
-- reviews
-- =====================================================================
alter table public.reviews enable row level security;

create policy "reviews_select_active_or_own" on public.reviews
  for select using (status = 'active' or reviewer_id = auth.uid() or public.is_admin());

create policy "reviews_insert_authenticated" on public.reviews
  for insert with check (auth.uid() = reviewer_id);

-- Reviewers cannot edit/delete their own review once posted (MVP simplicity,
-- prevents rating manipulation after the fact) — only admin can moderate.
create policy "reviews_admin_moderate" on public.reviews
  for update using (public.is_admin()) with check (public.is_admin());
create policy "reviews_admin_delete" on public.reviews
  for delete using (public.is_admin());

-- =====================================================================
-- contact_events — anonymous insert allowed by design (PHASE 1 decision)
-- =====================================================================
alter table public.contact_events enable row level security;

create policy "contact_events_insert_anyone" on public.contact_events
  for insert with check (true);

create policy "contact_events_select_owner_or_admin" on public.contact_events
  for select using (
    exists (select 1 from public.contractors c where c.id = contractor_id and c.user_id = auth.uid())
    or public.is_admin()
  );

-- No update/delete policy for anyone but admin — events are immutable.
create policy "contact_events_admin_delete" on public.contact_events
  for delete using (public.is_admin());

-- =====================================================================
-- reports
-- =====================================================================
alter table public.reports enable row level security;

create policy "reports_insert_anyone" on public.reports
  for insert with check (true);

create policy "reports_select_admin_only" on public.reports
  for select using (public.is_admin());

create policy "reports_admin_update" on public.reports
  for update using (public.is_admin()) with check (public.is_admin());

-- =====================================================================
-- admin_actions — admin only, no update/delete policy for anyone (immutable log)
-- =====================================================================
alter table public.admin_actions enable row level security;

create policy "admin_actions_admin_select" on public.admin_actions
  for select using (public.is_admin());

create policy "admin_actions_admin_insert" on public.admin_actions
  for insert with check (public.is_admin());

-- =====================================================================
-- system_settings — no direct table access for anon/authenticated;
-- read only via the get_setting() SECURITY DEFINER function (0011).
-- =====================================================================
alter table public.system_settings enable row level security;

create policy "system_settings_admin_all" on public.system_settings
  for all using (public.is_admin()) with check (public.is_admin());
-- Deliberately no select policy for non-admins: get_setting() bypasses
-- RLS via SECURITY DEFINER, so this table stays otherwise inaccessible.


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0014_reviews_hardening.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0014_reviews_hardening.sql
-- Depends on: 0005_contractors.sql, 0007_reviews.sql, 0013_rls_policies.sql
-- PHASE 9 — Contractor Reviews & Ratings.
--
-- Minimal, targeted fix for two gaps found while implementing the real
-- review-submission flow, neither requiring any new table/column:
--
-- 1. `reviews_insert_authenticated` (0013) only ever checked
--    `auth.uid() = reviewer_id` — nothing stopped an authenticated user
--    from submitting a review against a PENDING, REJECTED, or SUSPENDED
--    contractor. Issue #7 explicitly scopes review submission to
--    "an approved contractor"; this closes that gap at the one place a
--    client genuinely cannot route around it.
--
-- 2. `reviews_select_active_or_own` (0013) only ever checked the
--    review's OWN `status`, never the parent contractor's current
--    status — unlike `portfolio_images_select`/`contractor_categories_select`
--    (0013), which both already require the parent contractor to be
--    approved. A contractor that later gets suspended/rejected after
--    accumulating active reviews would keep those reviews publicly
--    queryable via a direct `GET /rest/v1/reviews?contractor_id=eq...`
--    call — unreachable through the normal profile-page flow (which
--    404s before ever calling getReviews()), but a real leak via direct
--    API access, exactly what Issue #7's "Test direct unauthorized
--    API/database requests" and "keep pending/rejected/suspended...
--    reviews out of public results" call out. Fixed to match the
--    existing portfolio_images/contractor_categories pattern: a
--    reviewer can always see their own review regardless of the
--    contractor's current status (so it doesn't just vanish from their
--    own view), admins see everything, and the public sees active
--    reviews only on currently-approved contractors.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Bound comment length — Issue #7 asks for "sensible validation and
-- length limits". Real, unspoofable enforcement (unlike an
-- application-level check alone, which only binds callers going through
-- this project's own UI/route) since it's a CHECK constraint. 2000
-- matches the bound already used for contractors.description
-- (src/lib/validation/contractorRegistration.ts).
-- ---------------------------------------------------------------------
alter table public.reviews
  add constraint reviews_comment_length check (comment is null or char_length(comment) <= 2000);

-- ---------------------------------------------------------------------
-- INSERT: reviewer identity was already unspoofable (auth.uid() =
-- reviewer_id); this adds "and the target contractor is approved".
-- ---------------------------------------------------------------------
drop policy "reviews_insert_authenticated" on public.reviews;

create policy "reviews_insert_authenticated" on public.reviews
  for insert with check (
    auth.uid() = reviewer_id
    and exists (
      select 1 from public.contractors c
      where c.id = contractor_id and c.status = 'approved'
    )
  );

-- ---------------------------------------------------------------------
-- SELECT: public visibility now requires BOTH the review's own
-- status = 'active' AND the parent contractor currently being
-- 'approved' — not just the review's own status. The reviewer's own
-- row and admin access are unaffected (unchanged from 0013).
-- ---------------------------------------------------------------------
drop policy "reviews_select_active_or_own" on public.reviews;

create policy "reviews_select_active_or_own" on public.reviews
  for select using (
    (
      status = 'active'
      and exists (
        select 1 from public.contractors c
        where c.id = contractor_id and c.status = 'approved'
      )
    )
    or reviewer_id = auth.uid()
    or public.is_admin()
  );


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0015_fix_review_stats_trigger_privileges.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0015_fix_review_stats_trigger_privileges.sql
-- Depends on: 0012_denormalized_field_triggers.sql
-- PHASE 9 — found while building real review submission end-to-end.
--
-- update_contractor_review_stats() (0012) is an AFTER INSERT/UPDATE/
-- DELETE trigger ON public.reviews that runs `UPDATE public.contractors
-- SET rating_avg = ..., review_count = ... WHERE id = ...`. It was
-- defined WITHOUT `security definer`, so it ran with the CALLING USER's
-- own privileges — meaning that internal UPDATE was itself subject to
-- RLS as if the calling user had issued it directly. `contractors_update_own`
-- (0013_rls_policies.sql) only allows `user_id = auth.uid() or
-- is_admin()` to update a contractors row.
--
-- Every review author is, by definition, NOT the contractor's owner (you
-- review someone else's business). So for any ordinary customer
-- submitting a review, this trigger's internal UPDATE matched zero rows
-- under RLS and silently did nothing — no error, just a rating_avg/
-- review_count that quietly stopped reflecting reality the moment a
-- non-admin, non-owner user (i.e. almost every real reviewer) posted a
-- review.
--
-- This was invisible in every prior test: the Phase 2 harness's F1-F3
-- trigger tests (supabase/local-dev/run-security-tests.mjs) all run
-- `asServiceRole`, which bypasses RLS entirely and so never exercised
-- this path; no review-SUBMISSION flow existed at all before Phase 9.
-- Caught here by a real end-to-end browser test (log in as an ordinary
-- customer, submit a review, check the displayed aggregate actually
-- changed) — not by any static check or the SQL-level harness as
-- originally written.
--
-- Fix: run the trigger function as its DEFINER (the migration-applying
-- role, effectively the schema owner) rather than the caller — the same
-- established pattern already used for handle_new_user() (0004) and
-- is_admin()/is_trusted_context() (0004) for exactly this class of
-- "a normal user's action needs to update a row they don't own, in a
-- narrowly-scoped, trigger-only way" problem. Direct EXECUTE is revoked
-- from public/anon/authenticated — this function has no legitimate use
-- outside its own trigger, and (per the same note on handle_new_user())
-- revoking EXECUTE does not affect the trigger mechanism's own ability
-- to invoke it.
-- =====================================================================

create or replace function public.update_contractor_review_stats()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  target_contractor_id uuid;
begin
  target_contractor_id := coalesce(new.contractor_id, old.contractor_id);

  update public.contractors
  set
    rating_avg = coalesce((
      select round(avg(rating)::numeric, 1)
      from public.reviews
      where contractor_id = target_contractor_id and status = 'active'
    ), 0),
    review_count = (
      select count(*)
      from public.reviews
      where contractor_id = target_contractor_id and status = 'active'
    )
  where id = target_contractor_id;

  return coalesce(new, old);
end;
$$;

revoke execute on function public.update_contractor_review_stats() from public, anon, authenticated;


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0016_contact_events_analytics.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0016_contact_events_analytics.sql
-- Depends on: 0008_contact_events.sql, 0012_denormalized_field_triggers.sql,
--             0015_fix_review_stats_trigger_privileges.sql
-- PHASE 10 — Usage & Contact Analytics (Issue #8).
--
-- 1. Widen contact_events.event_type to add 'website'.
--
--    contact_events (0008) only ever allowed 'phone' | 'line' | 'facebook'
--    | 'profile_view'. contractors.website_url (0002) exists and is
--    rendered as a clickable link on the public profile
--    (app/contractors/[slug]/page.tsx), but there has never been an
--    event_type a click on it could report — a gap explicitly disclosed
--    in src/lib/data/contactEvents.ts and src/components/ContactLink.tsx
--    since Phase 6/7. This migration closes it.
--
-- 2. Add contractors.profile_view_count.
--
--    Issue #8 asks for contractors to see how many times their profile
--    was viewed. contact_events already records a 'profile_view' row per
--    view, but counting them live on every profile/admin read would mean
--    an uncapped aggregate query on an unbounded table on every request.
--    Same denormalized-counter shape already used for rating_avg /
--    review_count (0012), kept in sync by a trigger below.
--
-- 3. update_contractor_view_count(): SECURITY DEFINER from the start.
--
--    This trigger's internal UPDATE ... WHERE id = contractor_id touches
--    a contractors row the *caller* essentially never owns — a
--    profile_view (or a phone/line/facebook/website click) is
--    overwhelmingly reported by an anonymous site visitor (`anon`), who
--    the RLS policy contractors_update_own (0013) does not authorize to
--    update that row at all. Phase 9 (0015) hit exactly this failure
--    mode reactively for update_contractor_review_stats(): a trigger
--    without `security definer` runs with the caller's own privileges,
--    so its internal UPDATE is itself subject to RLS and silently
--    matches zero rows for any caller who isn't the row's owner or an
--    admin. Applying that lesson proactively here rather than shipping
--    a counter that would have quietly never incremented for a real
--    anonymous visitor.
--
--    Direct EXECUTE is revoked from public/anon/authenticated for the
--    same reason as update_contractor_review_stats() and
--    handle_new_user(): this function has no legitimate purpose outside
--    its own trigger, and revoking EXECUTE does not affect the trigger
--    mechanism's own ability to invoke it.
-- =====================================================================

alter table public.contact_events drop constraint contact_events_event_type_check;
alter table public.contact_events add constraint contact_events_event_type_check
  check (event_type in ('phone', 'line', 'facebook', 'website', 'profile_view'));

alter table public.contractors
  add column profile_view_count integer not null default 0 check (profile_view_count >= 0);

comment on column public.contractors.profile_view_count is
  'Denormalized count of contact_events rows with event_type=profile_view for this contractor. Maintained by update_contractor_view_count() trigger on contact_events. PHASE 10.';

-- Backfill: contact_events rows already existed (recorded by Phase 6's
-- profile-view tracking) before this column existed. The trigger below
-- only recomputes on new INSERT/DELETE activity, so without this
-- one-time backfill every contractor's profile_view_count would sit at
-- its default of 0 -- silently wrong -- until their next profile view.
update public.contractors c
set profile_view_count = (
  select count(*)
  from public.contact_events ce
  where ce.contractor_id = c.id and ce.event_type = 'profile_view'
);

create or replace function public.update_contractor_view_count()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  target_contractor_id uuid;
begin
  target_contractor_id := coalesce(new.contractor_id, old.contractor_id);

  update public.contractors
  set profile_view_count = (
    select count(*)
    from public.contact_events
    where contractor_id = target_contractor_id and event_type = 'profile_view'
  )
  where id = target_contractor_id;

  return coalesce(new, old);
end;
$$;

revoke execute on function public.update_contractor_view_count() from public, anon, authenticated;

-- A single AFTER INSERT OR DELETE trigger cannot use a WHEN clause that
-- references NEW (NEW is null on DELETE, and Postgres rejects a WHEN
-- clause referencing NEW for a trigger that fires on DELETE at all — even
-- guarded by coalesce). Split into two triggers instead, each referencing
-- only the row variable that exists for its own event.
create trigger trg_update_contractor_view_count_ins
  after insert on public.contact_events
  for each row
  when (new.event_type = 'profile_view')
  execute function public.update_contractor_view_count();

create trigger trg_update_contractor_view_count_del
  after delete on public.contact_events
  for each row
  when (old.event_type = 'profile_view')
  execute function public.update_contractor_view_count();


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0017_search_keyword_trigram_index.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0017_search_keyword_trigram_index.sql
-- Depends on: 0005_contractors.sql
-- PHASE 13 — Performance & Production Hardening (Issue #11).
--
-- searchContractors() (src/lib/data/contractors.ts, Phase 5) matches a
-- free-text keyword with `business_name.ilike.%kw%,description.ilike.%kw%`
-- — a leading-wildcard ILIKE, which a plain btree index (or the implicit
-- ones this schema already has) structurally cannot accelerate at all,
-- regardless of table size. This was a real, disclosed limitation since
-- Phase 5's own report ("an unindexed ILIKE scan on existing columns...
-- an acceptable, documented limitation at MVP scale"); this is the phase
-- explicitly scoped to revisit exactly that kind of thing ahead of real
-- beta/production traffic.
--
-- Verified via EXPLAIN ANALYZE against the live seeded data (15 rows)
-- before this migration: `Seq Scan on contractors ... Filter: ...
-- business_name ~~* ... OR description ~~* ...`. At 15 rows this costs
-- ~0.1ms and is not remotely a real bottleneck yet — recorded honestly
-- in docs/PHASE13-PERFORMANCE-REPORT.md rather than overclaimed. The
-- point of this index is the query PLAN, not today's wall-clock time: a
-- sequential scan degrades linearly with table size and has no ceiling;
-- a trigram GIN index gives Postgres a real option to use instead once
-- the contractor count actually grows.
--
-- Partial (`where status = 'approved'`), matching searchContractors()'s
-- own query exactly — this is the ONLY status a keyword search ever
-- filters to (see the RLS-enforced `contractors_select_approved_public`
-- policy, 0013), so indexing pending/rejected/suspended rows here would
-- be pure waste.
-- =====================================================================

create extension if not exists pg_trgm;

create index idx_contractors_business_name_trgm
  on public.contractors using gin (business_name gin_trgm_ops)
  where status = 'approved';

create index idx_contractors_description_trgm
  on public.contractors using gin (description gin_trgm_ops)
  where status = 'approved';


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0018_grant_table_privileges.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0018_grant_table_privileges.sql
-- Depends on: every table migration above (0002-0011)
-- Issue #17 -- found in production: contractor registration failed with
-- Postgres error 42501 ("permission denied for table profiles") when
-- promoteNewAccountToContractor() (src/lib/auth/authService.ts) ran
-- `service_role client .from('profiles').update({role:'contractor'})`.
--
-- RLS and base table privileges are two SEPARATE Postgres layers.
-- `alter table ... enable row level security` (0013_rls_policies.sql)
-- only controls which ROWS a query can see/touch once it already has
-- privilege to run that kind of query on the table at all -- base
-- `GRANT ... ON TABLE` is the prerequisite RLS filters on top of, not
-- something RLS policies substitute for. Not one migration in this
-- directory ever ran a `grant ... on table` statement -- every table
-- created since 0002 has only ever worked because whatever bootstrapped
-- the running Postgres instance ALSO configured default privileges for
-- anon/authenticated/service_role, entirely outside this repo's own
-- migrations.
--
-- This exact gap was already known and already fixed -- just only for
-- the local-dev emulation, never for a real deployment:
-- supabase/local-dev/00_bootstrap.sql (Phase 2) grants this same set of
-- privileges to anon/authenticated/service_role with the comment
-- "default privileges are otherwise closed; RLS does the real gating" --
-- written specifically because a bare Postgres instance (unlike a
-- pre-configured hosted Supabase project) needs it spelled out. Issue
-- #17 shows the real hosted project needs the exact same thing spelled
-- out too, at least for `service_role` on `profiles` -- rather than
-- special-case just that one table/role, this ports the local-dev
-- harness's already-reasoned-through grant set verbatim into a real,
-- reproducible migration, so the schema no longer depends on whatever
-- default-privilege behavior a given Postgres host happens to apply.
--
-- Not a security change: RLS (0013) remains the actual authorization
-- boundary for anon/authenticated -- no policy is touched here, and a
-- base GRANT without a matching RLS policy still allows zero rows for
-- those two roles on any RLS-enabled table. service_role already
-- bypasses RLS entirely by design (that is its whole purpose, per
-- public.is_trusted_context()'s own comment in 0004_profiles.sql) --
-- granting it base table access is fixing a missing prerequisite for
-- its already-intended trust level, not adding a new one. Idempotent:
-- safe to run again if some tables already had grants and others didn't.
-- =====================================================================

grant usage on schema public to anon, authenticated, service_role;

grant select, insert, update, delete on all tables in schema public
  to anon, authenticated, service_role;

grant usage, select on all sequences in schema public
  to anon, authenticated, service_role;

-- So a future migration's `create table` doesn't reintroduce this same
-- gap for whichever role ends up applying it.
alter default privileges in schema public
  grant select, insert, update, delete on tables to anon, authenticated, service_role;

alter default privileges in schema public
  grant usage, select on sequences to anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0019_portfolio_image_limit.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0019_portfolio_image_limit.sql
-- Depends on: 0006_portfolio_images.sql
-- Issue #23 — "Never allow the total to exceed 20, including attempts
-- through direct API/REST calls." RLS (0013_rls_policies.sql) already
-- correctly scopes portfolio_images writes to the owning contractor (or
-- admin); it cannot express an AGGREGATE invariant like "at most 20 rows
-- for this contractor_id" — RLS policies evaluate one row at a time. A
-- BEFORE INSERT trigger is the correct tool for a count-based invariant,
-- the same reasoning already applied to every other cross-row rule in
-- this schema (e.g. rating_avg/review_count, 0012_denormalized_field_triggers.sql).
--
-- Applies to EVERY insert, unconditionally — including service_role
-- (the registration route's initial 0-5 images). Unlike the admin-field
-- locks (lock_contractor_admin_fields/lock_profile_role), this is not a
-- privilege-escalation guard where a trusted server context should be
-- allowed to bypass it; it is a plain data-integrity ceiling that must
-- hold no matter who is inserting.
-- =====================================================================

create or replace function public.enforce_portfolio_image_limit()
returns trigger
language plpgsql
as $$
declare
  current_count integer;
begin
  -- Serialize concurrent inserts for the SAME contractor so two
  -- simultaneous uploads can't both read a count under the cap and both
  -- land under it, pushing the real total past 20 — the same category
  -- of race decideContractor.ts's conditional UPDATE guards against for
  -- approve/reject (app/api/admin/_lib/decideContractor.ts), applied
  -- here via an advisory lock since this is an insert-count invariant,
  -- not a state-transition one. Held only for the rest of this
  -- transaction and only for this contractor_id — never blocks a
  -- different contractor's concurrent upload.
  perform pg_advisory_xact_lock(hashtext(new.contractor_id::text));

  select count(*) into current_count
  from public.portfolio_images
  where contractor_id = new.contractor_id;

  if current_count >= 20 then
    raise exception 'contractor % already has % portfolio images (maximum 20)', new.contractor_id, current_count
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

create trigger trg_portfolio_images_enforce_limit
  before insert on public.portfolio_images
  for each row execute function public.enforce_portfolio_image_limit();


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0020_portfolio_images_text_length_caps.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0020_portfolio_images_text_length_caps.sql
-- Depends on: 0006_portfolio_images.sql
-- Issue #28 — investigating a reported large-payload/413 failure on the
-- portfolio read path found that project_name/project_type/description/
-- location_text were all unconstrained `text` (effectively unbounded,
-- up to Postgres's ~1GB text limit). The app's own upload route
-- (app/api/contractors/me/portfolio/route.ts) already caps project_name
-- at 200 chars and never sets project_type/description/location_text at
-- all — but that's an app-level convention, not an enforced boundary: a
-- contractor's own valid bearer token is enough to write directly to
-- PostgREST (portfolio_images_owner_write, 0013_rls_policies.sql allows
-- any column value for their own contractor_id), bypassing the Next.js
-- route and its 200-char cap entirely. A single oversized value in any
-- of these columns would be returned in full by every read of that
-- contractor's portfolio (src/lib/data/portfolio.ts's getPortfolioImages
-- — used by both the public profile page and the contractor's own
-- manage page), which is exactly the shape of failure this issue
-- describes: a normally-tiny metadata response ballooning past a
-- platform payload limit. RLS already gates WHO can write; this adds
-- the bound on WHAT they can write, at the one layer that can't be
-- bypassed by skipping the app's own routes.
-- =====================================================================

alter table public.portfolio_images
  add constraint portfolio_images_project_name_length check (char_length(project_name) <= 200),
  add constraint portfolio_images_project_type_length check (char_length(project_type) <= 100),
  add constraint portfolio_images_description_length check (char_length(description) <= 2000),
  add constraint portfolio_images_location_text_length check (char_length(location_text) <= 300);


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0021_reports_hardening.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0021_reports_hardening.sql
-- Depends on: 0009_reports.sql, 0013_rls_policies.sql
-- Issue #35 security audit — two gaps found in the anonymous-insert
-- `reports` table, the same class of issue as 0020's portfolio_images
-- fix: RLS governs WHO can write a row, never WHAT the row can contain.
--
-- 1. `reason` was unconstrained `text` (unbounded, unlike every other
--    user-supplied text column in this schema — reviews.comment capped
--    at 2000 by 0014_reviews_hardening.sql, portfolio_images' four text
--    columns capped by 0020). `reports_insert_anyone` (0013) allows
--    `with check (true)` for anon, so any anonymous caller with the
--    public anon key can POST directly to PostgREST with an arbitrarily
--    large `reason` string — a storage-bloat/DoS vector into a table
--    only admins can even read.
--
-- 2. `reports_insert_anyone`'s `with check (true)` also never validated
--    `reporter_id` against the caller's own identity. `reporter_id` is
--    nullable specifically to allow anonymous reports (0009's own
--    comment), but nothing stopped an authenticated — or even fully
--    anonymous — caller from setting `reporter_id` to an ARBITRARY
--    other user's uuid, forging who filed a report. Impact is bounded
--    (only admins can ever read `reports`, via `reports_select_admin_only`),
--    but it's still an identity-spoofing gap in an admin-facing audit
--    trail an admin might reasonably act on. Fixed the same way
--    profiles/contact_events already require: a caller may only ever
--    claim to be themselves.
-- =====================================================================

alter table public.reports
  add constraint reports_reason_length check (char_length(reason) <= 2000);

drop policy "reports_insert_anyone" on public.reports;
create policy "reports_insert_anyone" on public.reports
  for insert
  with check (reporter_id is null or reporter_id = auth.uid());


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0022_storage_contractor_media_policies.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0022_storage_contractor_media_policies.sql
-- Depends on: nothing in this schema — targets Supabase's own `storage`
-- schema, which only exists on a real Supabase project (a plain local
-- Postgres install, this repo's local-dev harness included, has no
-- `storage` schema at all — see supabase/local-dev/README.md). The
-- whole body below is wrapped in an existence check so this migration
-- is a safe no-op locally and only takes effect against a real project.
--
-- Issue #35 security audit finding: `contractor-media` (the bucket
-- src/lib/storage/contractorMedia.ts writes to) has NEVER had its
-- access policy versioned anywhere in this repository. Every
-- application code path that writes to it already uses the
-- service_role admin client exclusively (that file's own header
-- comment) — which bypasses storage.objects RLS entirely regardless of
-- what policies exist. But that only describes what THIS APP's code
-- does; it says nothing about whether Supabase Storage's REST API would
-- also accept a direct upload/delete from the public anon key (shipped
-- to every browser by design) or an authenticated user's own key,
-- bypassing this app's server-side ownership checks
-- (requireContractorOwner()) entirely. Whatever the real project's
-- bucket currently allows for those roles has only ever lived in the
-- Supabase dashboard — unversioned, not visible in git history, and not
-- something this session can inspect or confirm (no access to the
-- hosted project). This migration makes the intended policy explicit
-- and enforced at the database level: public read (required — every
-- approved contractor's `<img src>` depends on it, see
-- contractorMedia.ts's own "public bucket, unguessable path" design
-- note), and no insert/update/delete policy for anon or authenticated
-- at all, so only service_role (which bypasses RLS) can write —
-- matching what the application code has always assumed, now actually
-- guaranteed by the database rather than by dashboard configuration
-- that could silently drift.
--
-- NOT behavior-tested by supabase/local-dev/run-security-tests.mjs:
-- that harness has no `storage` schema to test against (see above).
-- This can only be verified against a real hosted Supabase project.
-- =====================================================================

do $$
begin
  if to_regclass('storage.objects') is not null then
    execute $sql$
      drop policy if exists "contractor_media_public_read" on storage.objects;
      create policy "contractor_media_public_read" on storage.objects
        for select
        using (bucket_id = 'contractor-media');
    $sql$;
  end if;
end;
$$;


-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0023_category_icons.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0023_category_icons.sql
-- Depends on: 0003_categories.sql
-- Data-only migration: populates categories.icon for Issue #42's
-- Categories Layer B asset insertion.
-- =====================================================================

-- Issue #42, Layer B (Categories) — history of this file:
--   commit 6aafb90 (v1): reused the sheet's "ต่อเติมบ้าน" house icon for
--     สร้างบ้าน and approximated ถนน/งานระบบ/อื่นๆ from icons whose own
--     caption did not name them. Rejected by the Owner's blocker comment
--     (#5557507447) — accuracy outranks completeness for production data.
--   commit e578bb2 (v2): corrected to a strict rule — a category's icon
--     is set ONLY when a supplied sheet has a card whose OWN baked-in
--     caption names that exact category. 6/10 categories matched the
--     original 14-icon sheet (#5557421867); the other 4 (สร้างบ้าน, ถนน,
--     งานระบบ, อื่นๆ) had no qualifying asset and were left NULL, and
--     reported as missing rather than guessed (per the Owner's comment).
--   this version (v3): the Owner supplied a new 4-icon sheet in comment
--     #5557762471, explicitly captioned one-to-one with the 4 previously-
--     missing categories and their target asset paths (comment
--     #5557767814 — "EXECUTION — Categories Layer B: ใช้ไอคอน 4 หมวดที่
--     แนบมา"). All 4 now resolve to real, cropped assets. The 6 EXACT
--     mappings from v2 are unchanged.
--
-- Every icon file (all 10) was cropped from its source sheet with Pillow
-- (icon graphic only, caption/asset-path label text excluded, verified
-- pixel-by-pixel for stray artifacts) — no icon was redrawn, regenerated,
-- or AI-recreated.
--
-- Verified mapping table (production category -> sheet card used):
--   สร้างบ้าน (Home Building)    -> new 4-icon sheet, card captioned "สร้างบ้าน"     -> /icons/categories/1.webp   -- EXACT
--   ต่อเติม (Extension)         -> original sheet, card captioned "ต่อเติมบ้าน"      -> /icons/categories/2.webp   -- EXACT
--   รีโนเวท (Renovation)        -> original sheet, card captioned "ซ่อมแซม / รีโนเวท" -> /icons/categories/3.webp   -- EXACT
--   โครงสร้าง (Structural Work) -> original sheet, card captioned "งานโครงสร้าง"     -> /icons/categories/4.webp   -- EXACT
--   ไฟฟ้า (Electrical)          -> original sheet, card captioned "งานไฟฟ้า"        -> /icons/categories/5.webp   -- EXACT
--   ประปา (Plumbing)            -> original sheet, card captioned "งานประปา"        -> /icons/categories/6.webp   -- EXACT
--   หลังคา (Roofing)            -> original sheet, card captioned "งานหลังคา"       -> /icons/categories/7.webp   -- EXACT
--   ถนน (Road/Driveway)         -> new 4-icon sheet, card captioned "ถนน"           -> /icons/categories/8.webp   -- EXACT
--   งานระบบ (MEP Systems)       -> new 4-icon sheet, card captioned "งานระบบ"       -> /icons/categories/9.webp   -- EXACT
--   อื่นๆ (Other)               -> new 4-icon sheet, card captioned "อื่นๆ"          -> /icons/categories/10.webp  -- EXACT
--
-- All 10 production categories now have a verified, real asset. Nothing
-- is guessed or swapped between categories.
update public.categories set icon = case slug
  when 'สร้างบ้าน'  then '/icons/categories/1.webp'
  when 'ต่อเติม'    then '/icons/categories/2.webp'
  when 'รีโนเวท'    then '/icons/categories/3.webp'
  when 'โครงสร้าง'  then '/icons/categories/4.webp'
  when 'ไฟฟ้า'      then '/icons/categories/5.webp'
  when 'ประปา'      then '/icons/categories/6.webp'
  when 'หลังคา'     then '/icons/categories/7.webp'
  when 'ถนน'        then '/icons/categories/8.webp'
  when 'งานระบบ'    then '/icons/categories/9.webp'
  when 'อื่นๆ'       then '/icons/categories/10.webp'
  else icon
end
where slug in ('สร้างบ้าน', 'ต่อเติม', 'รีโนเวท', 'โครงสร้าง', 'ไฟฟ้า', 'ประปา', 'หลังคา', 'ถนน', 'งานระบบ', 'อื่นๆ');


