-- -----------------------------------------------------------------------------
-- SOURCE: supabase/migrations/0024_demo_contractors_qa43_seed.sql
-- -----------------------------------------------------------------------------
-- =====================================================================
-- 0024_demo_contractors_qa43_seed.sql
-- Issue #43 — QA/Demo Data: 76 synthetic contractors nationwide.
-- Generated by scripts/generate-demo-contractors-seed.mjs — do not hand-edit;
-- regenerate via that script instead so the SQL and the image files under
-- public/demo/qa43/ stay in sync.
--
-- Deliberately kept separate from migration 0023 (Issue #42 category icons)
-- and from all Home UI work — this is QA/demo data only, never represented
-- as real production contractors.
--
-- Coverage: 76 of Thailand's 77 provinces. บึงกาฬ (Bueng Kan, the newest
-- province, established 2011) is the ONE province intentionally left
-- uncovered, per the issue's own "do not create 77 records" rule.
--
-- Idempotent: every insert below is guarded by ON CONFLICT DO NOTHING on a
-- natural key (email / slug / id), so re-running this file is a no-op.
--
-- REMOVAL PROCEDURE (safe, single statement — cascades through every demo
-- row this migration creates: profiles, contractors, contractor_categories,
-- portfolio_images, reviews):
--   delete from auth.users where email like '%@demo43.invalid';
-- Then remove the generated image files (not tracked by the DB):
--   rm -rf public/demo/qa43
--
-- Trusted-context note: inserting into auth.users fires
-- handle_new_user(), which auto-creates a public.profiles row with the
-- default role ('customer') before this file's own profiles insert ever
-- runs — so that insert uses ON CONFLICT ... DO UPDATE to correct role/
-- full_name afterward. That UPDATE itself passes through
-- trg_profiles_lock_role, which discards role changes outside a trusted
-- context (public.is_trusted_context(): is_admin() or auth.role() =
-- 'service_role') — hence the request.jwt.claims set below, the same
-- technique supabase/local-dev/run-security-tests.mjs already uses to
-- exercise specific Postgres roles. The whole file runs as one
-- transaction so it is all-or-nothing.
-- =====================================================================

begin;
set local request.jwt.claims = '{"role":"service_role"}';

